const findColByHeader = (header) => {
    const n = norm(header);
    if (!n)
        return null;
    /* aliases are compared raw and normalized, so headers like "PR+ Quality %" match */
    return ALL_COLS.find(c => c.aliases.some(a => a === n || norm(a) === n)) || null;
};
